#include "inputs/audit_helpers.hpp"
#include "generated_diffeo.hpp"
std::array<double,20> RHS(const hyp::LayerPoint<double>&p,const Jet&u,double sigma){auto f=Parts(p,u,10,sigma,true);std::array<double,20>o{};for(int k=0;k<20;++k)o[k]=f.r[k].d+f.s[k].d/p.omega;return o;}
double Ndot(const hyp::LayerPoint<double>&p,const Jet&u,const std::array<double,20>&F,bool full=true){auto om=Omega(u,p);double wdot=om.normal.v*F[0];for(int i=0;i<3;++i)wdot+=p.domega[i]*F[4+i];wdot/=-p.alpha;double Gdot=full?F[1]*p.radius*p.radius:0.; // corrected a factors below via |dOmega|^2
 if(full){Gdot=0;for(int i=0;i<3;++i)Gdot+=F[1]*p.domega[i]*p.domega[i];double gm[3][3]{};const int ti[5]={0,0,0,1,1},tj[5]={0,1,2,1,2};for(int k=0;k<5;++k)gm[ti[k]][tj[k]]=gm[tj[k]][ti[k]]=F[7+k];gm[2][2]=-gm[0][0]-gm[1][1];for(int i=0;i<3;++i)for(int j=0;j<3;++j)Gdot-=gm[i][j]*p.domega[i]*p.domega[j];}
 return Gdot-2*om.normal.v*wdot;}
double Null(const hyp::LayerPoint<double>&p,const Jet&u){auto om=Omega(u,p);auto inv=hyp::Geometry(u.metric).inverse;D G{};for(int i=0;i<3;++i)for(int j=0;j<3;++j)G+=u.chi.value*inv[i][j]*om.gradient[i]*om.gradient[j];return (G-om.normal*om.normal).d;}
int main(){std::cout<<std::setprecision(17)<<"{\"controls\":[";bool first=true;double Cmax=0,Rmax=0,geo=0,geoN=0;const double w[4]={4,-6,4,-1};for(double a:{.5,.75,1.,2.})for(double sigma:{3.,5.})for(int dir=0;dir<2;++dir){const std::array<double,3>n=dir?std::array<double,3>{.36,-.48,.8}:std::array<double,3>{1,0,0};hyp::LayerReference<double>ref(1,a,{true,.05,.95});auto p0=ref.At(n[0],n[1],n[2]);for(int col=0;col<90;++col){auto u0=Initial(p0,a,col);auto ic=Constraints(u0,p0);for(double z:ic)Cmax=std::max(Cmax,std::abs(z));auto ir=Parts(p0,u0,10,sigma,true);double R=0;for(auto z:ir.s)R=std::max(R,std::abs(z.d));Rmax=std::max(Rmax,R);double N1[3]{},N1g[3]{},N0t[3]{},N0[3]{},Nfirst[3]{};std::array<double,20>F0{};
 for(int lev=0;lev<3;++lev)for(int k=0;k<4;++k){double O=std::ldexp(.001,-lev)*(k+1),r=std::sqrt(1-2*a*O);auto p=ref.At(r*n[0],r*n[1],r*n[2]);auto u=Initial(p,a,col);auto F=RHS(p,u,sigma);double g=0;for(int z=0;z<20;++z)if(z!=0&&(z<4||z>6))g=std::max(g,std::abs(F[z]));geo=std::max(geo,g);auto c=Constraints(u,p);for(double z:c)Cmax=std::max(Cmax,std::abs(z));double nd=Ndot(p,u,F),ndg=Ndot(p,u,F,false);geoN=std::max(geoN,std::abs(nd-ndg));N1[lev]+=w[k]*nd/p.omega;N1g[lev]+=w[k]*ndg/p.omega;N0t[lev]+=w[k]*nd;double nv=Null(p,u);N0[lev]+=w[k]*nv;Nfirst[lev]+=w[k]*nv/p.omega;if(lev==2)for(int z=0;z<20;++z)F0[z]+=w[k]*F[z];}
 auto next=Lift(p0.state);for(int z:{0,4,5,6})Seed(next,z,J(D(0,F0[z])));Consistent(next);auto nr=Parts(p0,next,10,sigma,true);double nextR=0;for(auto z:nr.s)nextR=std::max(nextR,std::abs(z.d));if(!first)std::cout<<',';first=false;std::cout<<"{\"a\":"<<a<<",\"sigma\":"<<sigma<<",\"dir\":"<<dir<<",\"col\":"<<col<<",\"initial_R0_error\":"<<R<<",\"initial_N0\":["<<N0[0]<<','<<N0[1]<<','<<N0[2]<<"],\"initial_N1\":["<<Nfirst[0]<<','<<Nfirst[1]<<','<<Nfirst[2]<<"],\"N0_t\":["<<N0t[0]<<','<<N0t[1]<<','<<N0t[2]<<"],\"N1_t_actual\":["<<N1[0]<<','<<N1[1]<<','<<N1[2]<<"],\"N1_t_geometric_zero_oracle\":["<<N1g[0]<<','<<N1g[1]<<','<<N1g[2]<<"],\"next_R0_error\":"<<nextR<<",\"F0\":[";for(int z=0;z<20;++z)std::cout<<(z?",":"")<<F0[z];std::cout<<"]}";}}
 std::cout<<"],\"summary\":{\"initial_constraints_max\":"<<Cmax<<",\"initial_R0_max\":"<<Rmax<<",\"stationary_geometric_first_RHS_max\":"<<geo<<",\"Ndot_geometric_residual_max\":"<<geoN<<"}}\n";}
